fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // We will produce at most maxsplit+1 parts per string.
    let max_parts = (maxsplit as usize).saturating_add(1);
    let mut result = Vec::with_capacity(a.len());
    for s in a {
        // Use rsplitn to split from the right, at most max_parts times.
        let mut parts: Vec<String> = s
            .rsplitn(max_parts, &sep)
            .map(|substr| substr.to_string())
            .collect();
        // rsplitn yields pieces from right→left; reverse to restore left→right order.
        parts.reverse();
        result.push(parts);
    }
    result
}